import java.util.*;class Node{int v;Node left,right;Node(int v){this.v=v;}}class Main{public static void main(String[] args){Node root=new Node(1);root.left=new Node(2);root.right=new Node(3);root.left.left=new Node(4);Queue<Node> q=new ArrayDeque<>();q.offer(root);while(!q.isEmpty()){Node n=q.poll();System.out.print(n.v+" ");if(n.left!=null)q.offer(n.left);if(n.right!=null)q.offer(n.right);}}}
